@startuml

class Elevator {
  + currentFloor : int
  + direction : string
  + move()
  + stop()
}

class ElevatorController {}

class Button {
  + isLit : boolean
}

class FloorButton extends Button {
  + floorNumber : int
  + direction : string
}

ElevatorController ..> Elevator : controls
ElevatorController ..> FloorButton : controls
Elevator "1" *-- "*" Button : has

@enduml

